-- Dust 2 utility lineups from misc/dust2smoke.json (64 rows).
-- Requires public.maps.slug = 'de_dust2'.
-- Coordinate normalization matches Mirage smoke exports (1006×1024 px → 0–1 radar space).

DELETE FROM public.utility_lineups WHERE map_id = (SELECT id FROM public.maps WHERE slug = 'de_dust2' LIMIT 1);

